INSERT INTO recipes(id,name,description,instructions,preparation_time_min,servings,created_at,updated_at) VALUES('67e9c783-c9c2-508f-bf90-bd2c7e9c05e9','Гречка на воде — гарнир','Компонент составного приёма пищи. Выход приблизительный, требует проверки.','Промойте 60 г сухой гречки. Добавьте примерно 120–150 мл воды, доведите до кипения. Готовьте под крышкой на слабом огне 15–20 минут, пока крупа не станет мягкой. Дайте постоять 5 минут. Готовый выход взвесьте: указанные 180 г являются приблизительной оценкой.',20,1,now(),now()) ON CONFLICT(id) DO NOTHING;
