INSERT INTO recipes(id,name,description,instructions,preparation_time_min,servings,created_at,updated_at) VALUES('4f5dc9ca-2f25-59d7-96ad-fa39f330dadd','Рис на воде — гарнир','Компонент составного приёма пищи. Выход приблизительный, требует проверки.','Промойте 60 г сухого риса. Добавьте воду по инструкции на упаковке. Варите под крышкой при слабом кипении до готовности, обычно 15–20 минут. Дайте постоять 5 минут. Ориентир выхода 180 г, фактический вес зависит от сорта и количества воды.',20,1,now(),now()) ON CONFLICT(id) DO NOTHING;
