INSERT INTO recipes(id,name,description,instructions,preparation_time_min,servings,created_at,updated_at) VALUES('e8b65198-5007-53a8-8d7a-ed9d05646d61','Макароны без соуса — гарнир','Компонент составного приёма пищи. Выход приблизительный, требует проверки.','Вскипятите воду. Опустите 70 г сухих макарон, перемешайте. Варите согласно времени на упаковке до готовности. Откиньте на дуршлаг и дайте воде стечь. Выход 170 г приблизительный, взвесьте готовые макароны.',12,1,now(),now()) ON CONFLICT(id) DO NOTHING;
