INSERT INTO recipes(id,name,description,instructions,preparation_time_min,servings,created_at,updated_at) VALUES('38b3668c-cdd7-58e3-b670-17f2f1a21a3c','Булгур на воде — гарнир','Компонент составного приёма пищи. Выход приблизительный, требует проверки.','Промойте 60 г булгура, если это рекомендует производитель. Добавьте воду согласно упаковке и варите при слабом кипении 15–20 минут. Оставьте под крышкой на 5 минут. Выход 180 г — кулинарная оценка, а не измерение.',20,1,now(),now()) ON CONFLICT(id) DO NOTHING;
