INSERT INTO recipes(id,name,description,instructions,preparation_time_min,servings,created_at,updated_at) VALUES('93e7a00b-ce25-5657-82d0-0f6dae8912c6','Куриное филе без гарнира','Компонент составного приёма пищи. Выход приблизительный, требует проверки.','Нарежьте 200 г сырого куриного филе небольшими кусочками. Разогрейте сковороду с 5 г масла, выложите филе. Обжарьте, затем добавьте немного воды и тушите под крышкой до полной готовности. При необходимости проверьте температуру пищевым термометром. Ориентировочный готовый выход 155 г необходимо уточнить взвешиванием.',20,1,now(),now()) ON CONFLICT(id) DO NOTHING;
