INSERT INTO recipes(id,name,description,instructions,preparation_time_min,servings,created_at,updated_at) VALUES('a6e25bff-116b-5597-8725-f78007bedeed','Индейка без гарнира','Компонент составного приёма пищи. Выход приблизительный, требует проверки.','Нарежьте 200 г сырого филе индейки небольшими кусочками. Нагрейте сковороду с 5 г масла. Готовьте, помешивая, затем добавьте немного воды и доведите до полной готовности под крышкой. Не ориентируйтесь только на цвет поверхности. Плановый выход 155 г приблизительный.',20,1,now(),now()) ON CONFLICT(id) DO NOTHING;
