INSERT INTO recipes(id,name,description,instructions,preparation_time_min,servings,created_at,updated_at) VALUES('ba5dc151-9ef9-556d-93c7-75b67db598e4','Огурцы и помидоры — овощная часть','Компонент составного приёма пищи. Выход приблизительный, требует проверки.','Вымойте овощи. Отмерьте 200 г съедобной части огурца и 200 г помидоров, нарежьте. Добавьте 5 г оливкового масла и перемешайте. Расчётный выход 405 г предполагает отсутствие потерь после взвешивания; при необходимости уточните его.',5,1,now(),now()) ON CONFLICT(id) DO NOTHING;
