INSERT INTO recipes(id,name,description,instructions,preparation_time_min,servings,created_at,updated_at) VALUES('e9d25f42-030d-50cc-a581-492a6581bb0b','Морковь с йогуртом — овощная часть','Компонент составного приёма пищи. Выход приблизительный, требует проверки.','Вымойте и очистите морковь. Взвесьте 150 г съедобной части и натрите. Добавьте 50 г натурального йогурта без сахара, перемешайте. Расчётный выход 200 г относится к взвешенным съедобным ингредиентам без нагрева.',8,1,now(),now()) ON CONFLICT(id) DO NOTHING;
